-- 038_interval_sessions.sql
-- Timed bodyweight sessions (callisthenics): a workout of kind interval
-- keeps what it was built from (focus, dumbbells, rhythm, minutes) in
-- interval_plan, and the library gains the exercises these sessions use, in
-- English, French and German.
--
-- Deploy: apply this file first, then the code. The app sends the new
-- workout column, and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE workouts ADD COLUMN IF NOT EXISTS interval_plan JSONB;

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, v.name, v.muscle_group, v.equipment, false, v.description, v.name_fr, v.name_de, v.description_fr, v.description_de
FROM (VALUES
  ('Burpee', 'full_body', 'bodyweight', 'Standing, put the hands down, jump the feet back to a plank, chest to the floor, jump the feet in and jump up.', 'Burpee', 'Burpee', 'Debout, mains au sol, sauter les pieds en arrière en planche, poitrine au sol, ramener les pieds et sauter.', 'Aus dem Stand Hände auf den Boden, Füße in den Stütz springen, Brust zum Boden, Füße zurück und hochspringen.'),
  ('Bodyweight Squat', 'legs', 'bodyweight', 'Feet shoulder-width apart, sit back and down until the thighs are parallel, chest up, stand up.', 'Squat au poids du corps', 'Kniebeuge ohne Gewicht', 'Pieds largeur d’épaules, s’asseoir en arrière jusqu’aux cuisses parallèles, buste droit, remonter.', 'Füße schulterbreit, nach hinten unten setzen bis die Oberschenkel parallel sind, Brust aufrecht, hochkommen.'),
  ('Jump Squat', 'legs', 'bodyweight', 'Squat down, then jump as high as possible and land softly back in the squat.', 'Squat sauté', 'Sprungkniebeuge', 'Descendre en squat, puis sauter le plus haut possible et se réceptionner en douceur dans le squat.', 'In die Kniebeuge gehen, so hoch wie möglich springen und weich in der Kniebeuge landen.'),
  ('Mountain Climber', 'core', 'bodyweight', 'In a high plank, drive the knees to the chest one after the other, fast, hips low.', 'Mountain climber', 'Bergsteiger', 'En planche bras tendus, ramener les genoux vers la poitrine l’un après l’autre, vite, hanches basses.', 'Im hohen Stütz die Knie abwechselnd schnell zur Brust ziehen, Hüfte tief.'),
  ('Jumping Jack', 'full_body', 'bodyweight', 'Jump the feet apart while raising the arms overhead, then jump back together.', 'Jumping jack', 'Hampelmann', 'Sauter pieds écartés en levant les bras au-dessus de la tête, puis revenir pieds joints.', 'Mit gegrätschten Beinen springen und die Arme über den Kopf heben, dann zurückspringen.'),
  ('High Knees', 'full_body', 'bodyweight', 'Run on the spot, bringing the knees up to hip height, on the balls of the feet.', 'Montées de genoux', 'Kniehebelauf', 'Courir sur place en montant les genoux à hauteur des hanches, sur l’avant des pieds.', 'Auf der Stelle laufen, Knie auf Hüfthöhe, auf den Fußballen.'),
  ('Reverse Lunge', 'legs', 'bodyweight', 'Step back and lower the back knee towards the floor, push through the front heel to return. Alternate legs.', 'Fente arrière', 'Ausfallschritt rückwärts', 'Reculer d’un pas et descendre le genou arrière vers le sol, pousser sur le talon avant pour revenir. Alterner.', 'Einen Schritt zurück, hinteres Knie Richtung Boden, über die vordere Ferse zurückdrücken. Beine abwechseln.'),
  ('Jumping Lunge', 'legs', 'bodyweight', 'In a lunge, jump and switch legs in the air, land softly in a lunge on the other side.', 'Fentes sautées', 'Sprungausfallschritte', 'Depuis une fente, sauter et changer de jambe en l’air, se réceptionner en douceur en fente de l’autre côté.', 'Aus dem Ausfallschritt springen, in der Luft die Beine wechseln und weich auf der anderen Seite landen.'),
  ('Skater Jump', 'legs', 'bodyweight', 'Leap sideways, one foot to the other, the trailing leg crossing behind.', 'Sauts de patineur', 'Eisschnellläufer-Sprünge', 'Bondir latéralement d’un pied sur l’autre, la jambe arrière croisant derrière.', 'Seitlich von einem Fuß auf den anderen springen, das hintere Bein kreuzt dahinter.'),
  ('Wall Sit', 'legs', 'bodyweight', 'Back against a wall, slide down until the knees are at 90 degrees and hold.', 'Chaise contre le mur', 'Wandsitzen', 'Dos au mur, descendre jusqu’aux genoux à 90 degrés et tenir.', 'Rücken an der Wand, hinabgleiten bis die Knie 90 Grad haben, und halten.'),
  ('Inchworm', 'full_body', 'bodyweight', 'Standing, walk the hands out to a plank, then walk the feet back to the hands and stand up.', 'Chenille (inchworm)', 'Raupe (Inchworm)', 'Debout, avancer les mains jusqu’à la planche, puis ramener les pieds vers les mains et se redresser.', 'Aus dem Stand mit den Händen in den Stütz laufen, dann die Füße zu den Händen bringen und aufrichten.'),
  ('Plank Shoulder Tap', 'core', 'bodyweight', 'In a high plank, tap each shoulder with the opposite hand without rocking the hips.', 'Planche avec touches d’épaule', 'Plank mit Schulterberührung', 'En planche bras tendus, toucher chaque épaule avec la main opposée sans balancer les hanches.', 'Im hohen Stütz mit jeder Hand die gegenüberliegende Schulter berühren, ohne die Hüfte zu bewegen.'),
  ('Bicycle Crunch', 'core', 'bodyweight', 'On your back, bring each elbow towards the opposite knee while extending the other leg.', 'Crunch vélo', 'Fahrrad-Crunch', 'Sur le dos, amener chaque coude vers le genou opposé en tendant l’autre jambe.', 'In Rückenlage jeden Ellbogen zum gegenüberliegenden Knie führen und das andere Bein strecken.'),
  ('Flutter Kicks', 'core', 'bodyweight', 'On your back, legs straight and off the floor, kick them up and down in small, quick movements.', 'Battements de jambes', 'Flutter Kicks', 'Sur le dos, jambes tendues décollées du sol, battre des jambes par petits mouvements rapides.', 'In Rückenlage die gestreckten Beine anheben und in kleinen, schnellen Bewegungen auf und ab schlagen.'),
  ('Crunch', 'core', 'bodyweight', 'On your back, knees bent, curl the shoulders off the floor using the abs, then lower slowly.', 'Crunch', 'Crunch', 'Sur le dos, genoux fléchis, enrouler les épaules avec les abdos, puis redescendre lentement.', 'In Rückenlage mit gebeugten Knien die Schultern mit den Bauchmuskeln anheben, dann langsam absenken.'),
  ('Lying Leg Raise', 'core', 'bodyweight', 'On your back, legs straight, raise them to vertical and lower them slowly without arching the back.', 'Relevés de jambes au sol', 'Beinheben liegend', 'Sur le dos, jambes tendues, les monter à la verticale et redescendre lentement sans cambrer.', 'In Rückenlage die gestreckten Beine senkrecht heben und langsam senken, ohne ins Hohlkreuz zu gehen.'),
  ('Hollow Hold', 'core', 'bodyweight', 'On your back, arms and legs extended and lifted, lower back pressed to the floor. Hold.', 'Hollow hold (position creuse)', 'Hollow Hold', 'Sur le dos, bras et jambes tendus et décollés, le bas du dos plaqué au sol. Tenir.', 'In Rückenlage Arme und Beine gestreckt anheben, unterer Rücken am Boden. Halten.'),
  ('Goblet Squat', 'legs', 'dumbbell', 'Hold a dumbbell against the chest, squat down between the knees, chest up, stand up.', 'Goblet squat', 'Goblet Squat', 'Un haltère contre la poitrine, descendre en squat entre les genoux, buste droit, remonter.', 'Eine Kurzhantel vor der Brust, zwischen die Knie in die Hocke gehen, Brust aufrecht, hochkommen.'),
  ('Dumbbell Thruster', 'full_body', 'dumbbell', 'Dumbbells at the shoulders, squat, then stand up and press them overhead in one movement.', 'Thruster aux haltères', 'Kurzhantel-Thruster', 'Haltères aux épaules, squatter puis se relever en les poussant au-dessus de la tête d’un seul mouvement.', 'Kurzhanteln an den Schultern, Kniebeuge, dann in einer Bewegung aufstehen und über Kopf drücken.'),
  ('Dumbbell Swing', 'full_body', 'dumbbell', 'Hold one dumbbell with both hands, hinge at the hips and swing it to chest height with a hip drive.', 'Swing avec haltère', 'Kurzhantel-Swing', 'Un haltère à deux mains, basculer des hanches et le lancer à hauteur de poitrine par une poussée des hanches.', 'Eine Kurzhantel beidhändig, aus der Hüfte beugen und sie mit einem Hüftstoß auf Brusthöhe schwingen.'),
  ('Renegade Row', 'back', 'dumbbell', 'In a high plank on two dumbbells, row one to the hip, then the other, without twisting the hips.', 'Rowing renegade', 'Renegade Row', 'En planche sur deux haltères, tirer l’un vers la hanche puis l’autre, sans tourner les hanches.', 'Im hohen Stütz auf zwei Kurzhanteln abwechselnd eine zur Hüfte ziehen, ohne die Hüfte zu drehen.'),
  ('Dumbbell Romanian Deadlift', 'legs', 'dumbbell', 'Dumbbells in front of the thighs, hinge at the hips with a flat back, then stand up by squeezing the glutes.', 'Soulevé de terre roumain aux haltères', 'Rumänisches Kreuzheben mit Kurzhanteln', 'Haltères devant les cuisses, basculer des hanches dos plat, puis se relever en serrant les fessiers.', 'Kurzhanteln vor den Oberschenkeln, mit geradem Rücken aus der Hüfte beugen, mit angespanntem Gesäß aufrichten.'),
  ('Dumbbell Reverse Lunge', 'legs', 'dumbbell', 'A dumbbell in each hand, step back to a lunge and push through the front heel to return. Alternate legs.', 'Fente arrière aux haltères', 'Ausfallschritt rückwärts mit Kurzhanteln', 'Un haltère dans chaque main, reculer en fente et pousser sur le talon avant pour revenir. Alterner.', 'Mit einer Kurzhantel in jeder Hand rückwärts in den Ausfallschritt und über die vordere Ferse zurück. Abwechseln.'),
  ('Dumbbell Sumo Squat', 'legs', 'dumbbell', 'Wide stance, toes out, hold a dumbbell between the legs and squat down, knees over the toes.', 'Squat sumo avec haltère', 'Sumo-Kniebeuge mit Kurzhantel', 'Pieds écartés, pointes vers l’extérieur, un haltère entre les jambes, descendre genoux au-dessus des pieds.', 'Breiter Stand, Fußspitzen nach außen, Kurzhantel zwischen den Beinen, Knie über den Zehen absenken.'),
  ('Dumbbell Push Press', 'shoulders', 'dumbbell', 'Dumbbells at the shoulders, dip slightly at the knees, then drive them overhead with the legs.', 'Push press aux haltères', 'Kurzhantel-Push-Press', 'Haltères aux épaules, fléchir légèrement les genoux puis les pousser au-dessus de la tête avec les jambes.', 'Kurzhanteln an den Schultern, leicht in die Knie, dann mit Beinschwung über Kopf drücken.'),
  ('Dumbbell Woodchop', 'core', 'dumbbell', 'Hold one dumbbell with both hands, rotate it diagonally, hip to above the opposite shoulder.', 'Bûcheron avec haltère', 'Holzhacker mit Kurzhantel', 'Un haltère à deux mains, le monter en diagonale de la hanche jusqu’au-dessus de l’épaule opposée.', 'Eine Kurzhantel beidhändig diagonal von der Hüfte bis über die gegenüberliegende Schulter führen.')
) AS v(name, muscle_group, equipment, description, name_fr, name_de, description_fr, description_de)
WHERE NOT EXISTS (SELECT 1 FROM exercises e WHERE e.user_id IS NULL AND e.name = v.name);

COMMIT;
